698	import { forSlot } from './registry';
699	
700	// ── Slots: regions of the UI that features fill ───────────────────────────────────────────────
701	// A SLOT is a region of the UI that features fill. Whatever renders a region does not list what
702	// goes in it; a contribution to a region (a panel, a table column, a row action, a toolbar
703	// control, a nav link) is a separate file, registered by discovery (slots/discover.ts).
704	//
705	//   1. declare a region  ->  slots/defs/projectDetail.ts
706	//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
707	//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
708	//   3. fill it           ->  features/projects/notes.slot.tsx
709	//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
710	//
711	// This file, slots/registry.ts and slots/discover.ts implement that mechanism; a region is
712	// declared by a file under slots/defs/.
713	
714	export type Contribution<Ctx> = {
715	  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
716	  order?: number;
717	  Component: ComponentType<Ctx>;
718	};
719	
720	export type SlotDef<Ctx extends object> = {
721	  id: string;
722	  /** Renders the region. Its props ARE the context handed to every contribution. */
723	  Slot: (ctx: Ctx) => ReactElement;
724	  /** A feature wraps its contribution in this, to be typed against the region's context. */
725	  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
726	};
727	
728	export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
729	  return {
730	    id,
731	    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
732	    // row actions are slots too), where a stray <div> would be invalid markup.
733	    Slot: (ctx: Ctx) =>
734	      createElement(
735	        Fragment,
736	        null,
737	        forSlot(id).map((c) =>
738	          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
739	        ),
740	      ),
741	    fill: (contribution) => ({ slot: id, ...contribution }),
742	  };
743	}
