792	
793	/**
794	 * Read and write ONE search-param key.
795	 *
796	 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
797	 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
798	 * reads the key does so directly. Search params are an open namespace (declared once in
799	 * routes/__root.tsx), so a new key needs no schema change.
800	 *
801	 *     const [status, setStatus] = useSearchParam('status', asString);
802	 */
803	export function useSearchParam<T>(
804	  key: string,
805	  decode: (raw: unknown) => T,
806	): [T, (value: T | undefined) => void] {
807	  const search = useSearch({ strict: false }) as Record<string, unknown>;
808	  const navigate = useNavigate();
809	
810	  const set = (value: T | undefined) => {
811	    void navigate({
812	      to: '.', // stay on the current route; only the search changes
813	      // Only the one key changes; every other param is left exactly as it was, so two controls
814	      // never clobber each other.
815	      search: (prev: Record<string, unknown>) => {
816	        const next = { ...prev };
817	        if (value === undefined || value === '') {
818	          delete next[key];
819	        } else {
820	          next[key] = value;
821	        }
822	        return next;
823	      },
824	      replace: true,
825	    });
826	  };
827	
828	  return [decode(search[key]), set];
829	}
