838	// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
839	// of a silent `if (res.ok)` that leaves the UI showing stale data.
840	// A non-2xx answer: its status tells a refusal (400) from a conflict with someone else's save (409).
841	export class HttpError extends Error {
842	  constructor(message: string, readonly status: number) {
843	    super(message);
844	  }
845	}
846	
847	async function send<T>(path: string, init?: RequestInit): Promise<T> {
848	  const res = await fetch(path, init);
849	  if (!res.ok) {
850	    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
851	  }
852	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
853	}
854	
855	export function getJson<T>(path: string): Promise<T> {
856	  return send<T>(path);
857	}
858	
859	// A change sends the signed-in name (`user`) as `X-User`, URI-encoded (a header is Latin-1 only),
860	// so the server records who made it.
861	const jsonHeaders = (user?: string): Record<string, string> =>
862	  user ? { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) } : { 'Content-Type': 'application/json' };
863	
864	export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
865	  return send<T>(path, {
866	    method: 'POST',
867	    headers: jsonHeaders(user),
868	    body: JSON.stringify(body),
869	  });
870	}
871	
872	export function putJson<T>(path: string, body?: unknown, user?: string): Promise<T> {
873	  return send<T>(path, {
874	    method: 'PUT',
875	    headers: jsonHeaders(user),
876	    body: body === undefined ? undefined : JSON.stringify(body),
877	  });
878	}
