880	import { useRef } from 'react';
881	import type { UseMutationResult } from '@tanstack/react-query';
882	
883	// Submits a mutation at most once at a time: a second submit (a double click) before the first has
884	// answered is dropped, so it stores one record, not two. `isPending` alone is not enough: it only
885	// disables the button once React has re-rendered, which a fast second click can beat.
886	export function useSubmitOnce<D, V, C>(mutation: UseMutationResult<D, Error, V, C>) {
887	  const busy = useRef(false);
888	  return (variables: V) => {
889	    if (busy.current) return;
890	    busy.current = true;
891	    mutation.reset();
892	    mutation.mutateAsync(variables).catch(() => undefined).finally(() => { busy.current = false; });
893	  };
894	}
