package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Reads the claim form from the body; refuses an amount that is missing, negative or has more than two
 * decimals, and a date that is not a calendar date. A blank date is left for the sheet's today.
 */
public class ValidateClaim {

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body) throws InvalidClaimException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        String date = request == null || request.date() == null ? "" : request.date().trim();
        String note = request == null || request.note() == null ? "" : request.note().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number, 0.00 or more, with up to two decimals.");
        }
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("Not a date: " + date);
            }
        }
        body.set(new ClaimInput(new BigDecimal(amount).setScale(2), parsed, note));
    }
}
package net.officefloor.hq.app.person;

/** The person form as submitted: a name and a grade, and for an edit the version of the person it loaded. */
public record PersonRequest(String name, String grade, Long version) {
}
package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Reads the person form from the body, trimming the name; refuses an empty name or a grade other than
 * A, B or C.
 */
public class ValidatePerson {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        body.set(new PersonRequest(name, grade, request.version()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a claim of the sheet by id. */
public class LoadClaim {
    public void load(@Val Sheet sheet, @PathVariable("claimId") String claimId, ClaimRepository repository,
            Out<Claim> claimOut) throws ClaimNotFoundException {
        Long id;
        try {
            id = Long.valueOf(claimId.trim());
        } catch (NumberFormatException e) {
            throw new ClaimNotFoundException(claimId);
        }
        claimOut.set(repository.findByIdAndSheetId(id, sheet.getId())
                .orElseThrow(() -> new ClaimNotFoundException(claimId)));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the new today from the body; refuses anything that is not a calendar date. */
public class ValidateToday {

    public record TodayRequest(String today) {
    }

    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today) throws InvalidTodayException {
        String raw = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(raw));
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException(raw);
        }
    }
}
